write_tree('CSCA 412', 'Object Oriented Programming', 1, [
 ('I', 'Introduction to C++ and User Defined Functions', [
  ('Introduction to C++', 'C++ is a general purpose language that extends C with classes and objects, giving both low level control and object oriented features.',
   [('Applications of C++', 'Used for operating systems, games, embedded software, banking systems, compilers and performance critical libraries.'),
    ('History and features of C++', 'Developed by Bjarne Stroustrup as C with classes; features include classes, objects, encapsulation, polymorphism, templates and exception handling.'),
    ('C++ versus C', 'C is procedural with no classes, while C++ supports objects, function overloading, references, namespaces and the standard template library.')]),
  ('Structure of a Simple C++ Program', 'A C++ program has preprocessor directives, a main function and statements, with optional class and function definitions above main.',
   [('Header files and preprocessor directives', 'Lines beginning with # such as #include <iostream> pull in library declarations before compilation.'),
    ('Namespace std', 'A container that holds library names like cout, so you must write std::cout or add using namespace std.'),
    ('The main function', 'The entry point returning an int status code, where execution begins and ends.'),
    ('Comments and indentation', 'Single line // comments and block /* */ comments keep the code readable and are ignored by the compiler.')]),
  ('Compiling and Executing C++ Programs', 'The source file passes through preprocessing, compilation, assembly and linking to become an executable.',
   [('Preprocessor stage', 'Expands directives such as #include and #define before the actual compilation.'),
    ('Compiler and assembler stages', 'The compiler turns source into object code and the assembler produces machine level object files.'),
    ('Linker stage', 'Joins the object files with library code to produce the final executable.'),
    ('Runtime errors and debugging', 'Syntax errors are caught by the compiler while logic errors surface only while running, so debugging with breakpoints is used.')]),
  ('Programming Elements', 'The basic building blocks of a program are tokens, data types, variables, constants, operators and control statements.',
   [('Tokens, keywords and identifiers', 'The smallest units such as keywords, identifiers, constants, strings and operators that the compiler recognises.'),
    ('Data types and variables', 'Fundamental types int, float, double, char and bool with modifiers, plus user defined types such as class.'),
    ('Operators and expressions', 'Arithmetic, relational, logical, assignment, increment and bitwise operators combine operands into expressions.'),
    ('Control statements', 'Selection with if, if else and switch, and repetition with for, while and do while.'),
    ('Input and output with cin and cout', 'Stream operators >> and << read from the keyboard and write to the screen.')]),
  ('C++ Library Functions', 'The standard library supplies ready made functions grouped in headers such as iostream, cmath, cstring and cstdlib.',
   [('iostream and string functions', 'Provide stream input output and text manipulation such as strlen, strcpy and strcmp.'),
    ('math and utility functions', 'sqrt, pow, abs, ceil and floor come from cmath; rand and atoi come from cstdlib.'),
    ('Why libraries are used', 'Reusing tested library code shortens development time and reduces programming errors.')]),
  ('User Defined Functions', 'A user defined function packages a task with a name, a parameter list and a return type so it can be called repeatedly.',
   [('Function declaration, definition and call', 'The prototype announces the signature, the definition holds the body and the call passes control with arguments.'),
    ('Return values and void functions', 'A function returns one value of the stated type, or returns nothing when declared void.'),
    ('Actual and formal parameters', 'Actual parameters are the values passed at the call site; formal parameters are the names receiving them inside the function.'),
    ('Default arguments and inline functions', 'Default values let some arguments be omitted, and inline functions expand the body at the call site to avoid call overhead.')]),
  ('Parameter Passing: Call by Value and Call by Reference', 'Call by value copies the argument so the original is unchanged, while call by reference passes the address so the function can modify the caller variable.',
   [('Call by value', 'A duplicate of the value reaches the function, so changes stay local - swapping two numbers this way does not work.'),
    ('Call by reference using references', 'The reference parameter is another name for the same variable, so changes are visible to the caller.'),
    ('Call by address using pointers', 'The pointer parameter holds the address, and the function dereferences it to modify the original value.'),
    ('Choosing between them', 'Use call by value for small read only data and call by reference for large objects or when results must come back through parameters.')])
 ]),
 ('II', 'Object Oriented Concepts, Classes, Overloading and Inheritance', [
  ('Object Oriented Programming Paradigm', 'OOP organises a program around objects that combine data and the functions that operate on that data.',
   [('Procedural versus object oriented approach', 'Procedural programming follows functions and global data, while OOP follows objects with encapsulated state and behaviour.'),
    ('Basic OOP concepts', 'The core ideas are class, object, encapsulation, abstraction, inheritance, polymorphism and message passing.'),
    ('Benefits of OOP', 'Reusability through inheritance, easier maintenance, data security by encapsulation and natural modelling of real world entities.'),
    ('Applications of OOP', 'Used in simulation, GUI software, databases, CAD systems and large business applications.')]),
  ('C++ Class Definition and Member Functions', 'A class is a user defined type that bundles data members and member functions, and an object is one instance of that class.',
   [('Class specification and access specifiers', 'Members are declared private, protected or public; private members are reachable only inside the class.'),
    ('Member functions inside and outside the class', 'Small functions can be defined inline in the class, while larger ones are declared inside and defined outside using the scope resolution operator.'),
    ('Objects and memory', 'Each object gets its own copy of the data members, while member functions are shared by all objects of the class.'),
    ('The this pointer', 'A hidden pointer inside every member function that refers to the object on which the function was called.')]),
  ('Static Members', 'A static data member is shared by all objects of the class and a static member function can be called without any object.',
   [('Static data member', 'Declared inside the class and defined once outside; only one copy exists for the whole class.'),
    ('Static member function', 'Has no this pointer, so it can access only static members and other static functions.'),
    ('Use cases', 'Counting the number of objects created, keeping shared configuration values and implementing utility functions.')]),
  ('Constructors and Destructors', 'A constructor initialises an object when it is created, and a destructor releases its resources when it is destroyed.',
   [('Default constructor', 'Takes no arguments and is supplied by the compiler if no constructor is written.'),
    ('Parameterised constructor', 'Accepts arguments so an object can be created with initial values, as in Student s(101, "Ravi").'),
    ('Copy constructor', 'Creates a new object as a copy of another, taking a reference to the same class; needed to avoid shallow copying of pointers.'),
    ('Dynamic constructor', 'Allocates memory at run time using new, which the destructor must free with delete.'),
    ('Destructor', 'Named with a tilde, takes no arguments and runs automatically when the object goes out of scope or is deleted.'),
    ('Constructor overloading', 'Several constructors with different parameter lists let objects be built in different ways.')]),
  ('Operator Overloading', 'Operator overloading gives an extra meaning to an existing operator so it works on user defined types such as complex numbers.',
   [('Unary operator overloading', 'Operators with one operand, such as ++, -- and unary minus, are overloaded with no argument or with a dummy int for postfix.'),
    ('Binary operator overloading', 'Operators with two operands such as +, - and * are overloaded with one parameter, or as friend functions with two.'),
    ('Rules of operator overloading', 'New operators cannot be invented, precedence and arity cannot change, and operators such as :: and sizeof cannot be overloaded.'),
    ('Type conversions', 'Conversion between basic and user defined types is done by constructor conversion and by conversion operator functions.')]),
  ('Function Overloading, Friend and Virtual Functions', 'C++ allows several functions with the same name but different parameter lists, and provides friend and virtual functions for special access and late binding.',
   [('Function overloading', 'The compiler picks the correct version from the number or types of the arguments - the return type alone cannot distinguish them.'),
    ('Friend function and friend class', 'A non member function or another class granted access to the private members of the class that declares it.'),
    ('Virtual function', 'A member function declared virtual is chosen at run time based on the actual object, which is how runtime polymorphism works.'),
    ('Pure virtual function and abstract class', 'A virtual function with no body makes the class abstract, so objects cannot be created but derived classes must implement it.'),
    ('Static versus dynamic binding', 'Normal calls are resolved at compile time while virtual calls are resolved at run time through the vtable.')]),
  ('Inheritance and Its Types', 'Inheritance lets a new class reuse and extend the members of an existing class, expressing an is-a relationship.',
   [('Base and derived class', 'The base class supplies common members and the derived class adds or overrides behaviour.'),
    ('Single inheritance', 'One derived class inherits from exactly one base class.'),
    ('Multiple inheritance', 'One derived class inherits from more than one base class, which can cause ambiguity between same named members.'),
    ('Multilevel inheritance', 'A chain such as A to B to C, where each level inherits from the previous one.'),
    ('Hierarchical inheritance', 'Several classes inherit from one common base class.'),
    ('Hybrid inheritance', 'A combination of two or more inheritance forms, usually built from multiple and multilevel.'),
    ('Virtual base class', 'Declaring a base virtual ensures that only one copy of its members survives the diamond problem of multiple inheritance.'),
    ('Applications of inheritance', 'Code reuse, building class libraries and frameworks, and modelling taxonomies such as Shape and Circle.')])
 ]),
 ('III', 'Java Applets, Graphics, Files and Collections', [
  ('Introduction to Java Applet Programming', 'An applet is a small Java program that used to be embedded in a web page and executed inside the browser.',
   [('What an applet is', 'A class extending Applet or JApplet whose execution is controlled by the browser or applet viewer.'),
    ('Applet life cycle', 'init, start, paint, stop and destroy are called by the browser at the appropriate moments.'),
    ('Applet versus application', 'An application starts at main and runs on its own, while an applet has no main, is embedded in HTML and is restricted by the browser sandbox.'),
    ('Why applets are obsolete', 'Browsers removed plugin support, so applets are replaced by Java Web Start and modern web technologies.')]),
  ('Graphic Programming in Java', 'The Graphics class provides drawing primitives for lines, rectangles, ovals, polygons, strings and images.',
   [('Coordinate system and Graphics object', 'The origin is the top left corner and the Graphics object supplied to paint performs all drawing.'),
    ('Drawing shapes and text', 'Methods such as drawLine, drawRect, fillRect, drawOval, drawPolygon and drawString draw the primitives.'),
    ('Colours and fonts', 'setColor with the Color class and setFont with the Font class control appearance.'),
    ('Animation basics', 'Shapes are redrawn in a loop after a delay, usually inside the paint method, to create movement.')]),
  ('Managing Input and Output Files', 'Java file handling reads and writes data through stream classes, with character streams for text and byte streams for binary data.',
   [('File and FileWriter or FileReader', 'The File class represents a path while FileReader and FileWriter transfer characters to and from a file.'),
    ('BufferedReader and BufferedWriter', 'Wrap the character streams to buffer data, which reduces the number of slow disk operations.'),
    ('Streams versus readers', 'InputStream and OutputStream work on bytes while Reader and Writer work on characters with encoding.'),
    ('Exception handling during file operations', 'File operations throw IOException, so try, catch and finally blocks are required.')]),
  ('Java Collections Framework', 'The collections framework provides ready made data structures such as lists, sets, maps and queues together with iterators.',
   [('Lists: ArrayList and LinkedList', 'ArrayList keeps a growable array with fast index access; LinkedList uses nodes and is faster for insertion at the ends.'),
    ('Sets: HashSet and TreeSet', 'HashSet stores unique elements without order while TreeSet keeps them sorted.'),
    ('Maps: HashMap and TreeMap', 'Store key value pairs; HashMap has no order while TreeMap iterates in sorted key order.'),
    ('Queue and Deque interfaces', 'Used for FIFO and double ended queue behaviour, with PriorityQueue for priority order.'),
    ('Iterator and the for-each loop', 'The Iterator walks through a collection and may remove elements safely during traversal.'),
    ('Comparison with arrays', 'Collections resize automatically, hold objects and provide algorithms such as sort and search through the Collections class.')])
 ]),
 ('IV', 'Event Handling, Applets and AWT', [
  ('Event Handling', 'Event handling responds to user actions by notifying listener objects that the event has occurred.',
   [('Delegation event model', 'A source generates an event object and sends it to registered listener objects that implement the matching interface.'),
    ('Event classes', 'ActionEvent, MouseEvent, KeyEvent, ItemEvent and WindowEvent carry details such as source and modifiers.'),
    ('Listener interfaces and adapter classes', 'ActionListener, MouseListener and KeyListener receive events, and adapter classes provide empty implementations of their methods.'),
    ('Registering listeners', 'addActionListener, addMouseListener and addKeyListener connect a component to its handler.'),
    ('Common statements inside a handler', 'Determining the source and performing the required action such as validating a form or closing a window.')]),
  ('AWT: Working with Windows, Graphics and Text', 'The Abstract Window Toolkit provides the original Java classes for windows, controls, graphics and text.',
   [('Frame and window basics', 'Frame creates a top level window with a title bar, while Panel groups components inside it.'),
    ('Components and containers', 'Controls are added to containers such as Frame and Panel using add.'),
    ('Drawing on a component', 'The paint method draws lines, shapes and text on the component surface.'),
    ('Text output with fonts', 'drawString plus the Font and FontMetrics classes position and measure text.')]),
  ('AWT Controls', 'AWT supplies standard controls for user input, each with its own event type.',
   [('Labels and buttons', 'Label displays fixed text and Button raises an ActionEvent when clicked.'),
    ('Text fields and text areas', 'TextField accepts one line and TextArea accepts multiple lines of input.'),
    ('Checkbox, choice and list', 'Checkbox toggles a state, Choice is a drop down list and List shows a scrollable list of items.'),
    ('Scrollbars and layout within controls', 'Scrollbar values generate adjustment events and are used for sliders or scrolling.')]),
  ('Layout Managers and Menus', 'Layout managers decide the position and size of components, and menus provide a standard menu bar interface.',
   [('FlowLayout', 'Arranges components left to right and wraps to the next line, like words on a page.'),
    ('BorderLayout', 'Places components in five regions: north, south, east, west and centre.'),
    ('GridLayout and CardLayout', 'GridLayout arranges components in equal sized cells, CardLayout stacks components so only one is visible at a time.'),
    ('GridBagLayout', 'The most flexible manager, using constraints for grid position, weight and fill of each component.'),
    ('MenuBar, Menu and MenuItem', 'A frame holds one menu bar, each menu holds items, and selecting an item raises an action event.')]),
  ('Working with Images', 'Images are loaded with getImage or ImageIcon and drawn with drawImage, and can be manipulated pixel by pixel.',
   [('Loading an image', 'getImage needs an applet or Toolkit context, while ImageIcon works in any application.'),
    ('Drawing an image', 'drawImage paints it at a position and with an optional size, and it may load asynchronously.'),
    ('Image processing basics', 'Pixel arrays from PixelGrabber allow filters, cropping and resizing.')])
 ]),
 ('V', 'Java Swing, Java Beans and Servlets', [
  ('Java Swing and Its Controls', 'Swing is a lightweight component library built on AWT that provides richer and platform independent controls.',
   [('JFrame, JPanel and container hierarchy', 'JFrame is the top level window, its content pane holds components and JPanel groups them.'),
    ('Common Swing controls', 'JButton, JLabel, JTextField, JTextArea, JCheckBox, JRadioButton, JComboBox, JList and JTable.'),
    ('Swing versus AWT', 'Swing components are lightweight and drawn by Java, AWT components are heavyweight and depend on the operating system.'),
    ('Dialogs and message boxes', 'JOptionPane shows messages and collects simple input without building a whole form.'),
    ('Menus and toolbars in Swing', 'JMenuBar, JMenu and JMenuItem together with JToolBar create the standard application interface.')]),
  ('Java Beans', 'A Java Bean is a reusable software component that follows naming conventions so tools can inspect and manipulate it.',
   [('Properties of a bean', 'Private fields exposed through getter and setter methods that follow the getX and setX pattern.'),
    ('Introspection', 'Tools discover a bean properties, methods and events automatically from the naming conventions.'),
    ('Events and bound properties', 'A bean can notify listeners when a property changes using the event model.'),
    ('Bean Development Kit usage', 'The BDK allowed beans to be assembled visually in a builder tool without writing code.'),
    ('Advantages of beans', 'Reusability, visual assembly and configuration through properties.')]),
  ('Servlets', 'A servlet is a Java class that runs on a web server and generates dynamic web content in response to HTTP requests.',
   [('Servlet life cycle', 'The container calls init once, service for every request and destroy before removing it.'),
    ('HttpServlet and doGet or doPost', 'GET carries parameters in the URL for retrieval, POST carries them in the request body for submission.'),
    ('Request and response objects', 'HttpServletRequest supplies parameters and HttpServletResponse writes the reply, with content type set first.'),
    ('Session tracking', 'Cookies, hidden form fields and HttpSession maintain state between separate HTTP requests.'),
    ('Servlet versus CGI', 'Servlets stay loaded in memory and handle each request in a thread, while CGI starts a new process per request.'),
    ('Deployment', 'A web.xml descriptor or annotations map URLs to servlet classes inside a web container such as Tomcat.')])
 ])
])

write_tree('CSCA 413', 'Database Management Systems', 1, [
 ('I', 'Introduction and Data Modelling', [
  ('File Systems versus Database Systems', 'A file system stores data in separate application files, while a DBMS stores it centrally with controlled sharing and integrity.',
   [('Drawbacks of file processing', 'Data redundancy, inconsistency, difficulty of concurrent access, weak security and program data dependence.'),
    ('Advantages of a DBMS', 'Controlled redundancy, shared data, integrity constraints, backup and recovery, security and data independence.'),
    ('When a DBMS is not suitable', 'Small single user applications with simple fixed data may not justify the cost and complexity of a DBMS.')]),
  ('Data Models', 'A data model is a collection of concepts for describing the structure of a database and the operations allowed on it.',
   [('Hierarchical model', 'Organises data as a tree of parent and child records, where each child has exactly one parent.'),
    ('Network model', 'Uses a graph of records where a child may have more than one parent, handled through sets and pointers.'),
    ('Relational model', 'Represents data as tables of rows and columns with keys and relationships expressed by matching values.'),
    ('Object based and object relational models', 'Store complex objects, classes and inheritance, with object relational systems adding these ideas to relational tables.'),
    ('Entity relationship model', 'A conceptual, diagrammatic model of entities, attributes and relationships used before implementation.')]),
  ('DBMS Architecture', 'A DBMS is organised in levels so that users, the logical design and the physical storage remain independent of one another.',
   [('Three schema architecture', 'External or view level for individual users, conceptual level for the logical design and internal level for physical storage.'),
    ('Data abstraction', 'Hides storage detail from users and shows only the level of detail each user needs.'),
    ('Database administrator and users', 'The DBA designs and maintains the schema and controls access, while end users, application programmers and analysts use the data.'),
    ('Database languages', 'DDL defines structures, DML manipulates data, DCL controls privileges and TCL manages transactions.')]),
  ('Data Independence', 'Data independence means that a change at one level of the schema does not force changes at a higher level.',
   [('Logical data independence', 'Changing the conceptual schema, such as adding a column, need not change the external views or the application programs.'),
    ('Physical data independence', 'Changing storage structures such as adding an index need not change the conceptual schema.'),
    ('How independence is achieved', 'By keeping separate schema levels and mapping each level to the next.')]),
  ('Data Modelling Using the Entity Relationship Model', 'The ER model describes data as entities, their attributes and the relationships between them, drawn as a diagram.',
   [('Entity and entity set', 'An entity is a real world object such as a student and an entity set is a collection of similar entities.'),
    ('Attributes and their types', 'Simple, composite, single valued, multivalued, derived and key attributes describe the properties of an entity.'),
    ('Relationship and relationship set', 'An association among entities such as enrols between student and course.'),
    ('Degree and cardinality ratio', 'Degree counts participating entity sets; cardinality is one to one, one to many, many to one or many to many.'),
    ('Participation constraints', 'Total participation means every entity takes part, partial means only some do.'),
    ('Keys in ER design', 'Super key, candidate key, primary key and foreign key identify entities and link them.'),
    ('Weak entity set', 'An entity set without a key of its own, identified only through its owner entity with a partial key.'),
    ('ER diagram notation', 'Rectangles for entities, ellipses for attributes, diamonds for relationships, double lines for total participation.')]),
  ('Enhanced ER Modelling', 'Enhanced ER modelling adds abstraction tools such as specialisation, generalisation, aggregation and categories.',
   [('Specialisation and generalisation', 'Specialisation splits a superclass into subclasses, generalisation combines similar entities into a superclass.'),
    ('Attribute inheritance', 'A subclass inherits all attributes of its superclass and adds its own.'),
    ('Constraints on specialisation', 'Disjoint or overlapping subclasses, and total or partial participation in the specialisation.'),
    ('Aggregation', 'Treats a relationship as a higher level entity so it can take part in another relationship.'),
    ('Category and union type', 'A subclass whose members come from a union of several different superclasses, shown with a union circle.')])
 ]),
 ('II', 'Relational Model, SQL, Design and Normalisation', [
  ('Relational Model Concepts', 'The relational model stores data in relations (tables) of tuples (rows) and attributes (columns) drawn from domains.',
   [('Relation, tuple, attribute and domain', 'A relation is a table, a tuple is a row, an attribute is a named column and a domain is the set of allowed values.'),
    ('Degree and cardinality', 'Degree counts the attributes or columns and cardinality counts the tuples or rows.'),
    ('Keys of a relation', 'Super key uniquely identifies a tuple, candidate keys are minimal super keys, one becomes the primary key and foreign keys reference other relations.'),
    ('Integrity constraints', 'Entity integrity forbids NULL primary keys and referential integrity requires a foreign key to match some existing primary key or be NULL.'),
    ('Codd rules', 'Twelve rules described by E F Codd that a full relational DBMS should satisfy.')]),
  ('Relational Algebra', 'Relational algebra is a procedural query language of operators that take relations and produce a new relation.',
   [('Selection and projection', 'Selection (sigma) chooses rows satisfying a condition; projection (pi) chooses a subset of columns.'),
    ('Set operations', 'Union, intersection, set difference and Cartesian product combine relations with compatible schemas.'),
    ('Join operations', 'Theta join, equi join and natural join combine matching rows; outer joins keep unmatched rows padded with NULL.'),
    ('Division operation', 'Returns tuples of one relation that match every tuple of another, used for questions like "students who took all courses".'),
    ('Renaming and assignment', 'The rho operator renames relations or attributes and the assignment operator names intermediate results.')]),
  ('SQL: Basic and Complex Queries', 'SQL is the standard language for defining and querying relational databases, written as declarative statements.',
   [('DDL, DML, DCL and TCL', 'DDL creates and alters structures, DML selects and modifies rows, DCL grants privileges and TCL commits or rolls back transactions.'),
    ('Basic SELECT queries', 'SELECT columns FROM table WHERE condition with DISTINCT, ORDER BY, BETWEEN, IN and LIKE.'),
    ('Aggregate functions and grouping', 'COUNT, SUM, AVG, MIN and MAX with GROUP BY and HAVING for conditions on groups.'),
    ('Joins in SQL', 'Inner join, left, right and full outer joins in both the classic and ANSI syntax.'),
    ('Subqueries and correlated queries', 'Nested SELECT statements, including EXISTS, ANY and ALL comparisons against inner results.'),
    ('UPDATE, DELETE and INSERT', 'Statements that modify the contents of existing relations.'),
    ('Views', 'A stored query acting as a virtual table, used for security and simplified access; updatable only under restrictions.'),
    ('Constraints', 'NOT NULL, UNIQUE, PRIMARY KEY, FOREIGN KEY, CHECK and DEFAULT enforce rules at the schema level.')]),
  ('Relational Calculus', 'Relational calculus is a non procedural query language that describes what result is wanted rather than how to compute it.',
   [('Tuple relational calculus', 'Describes the set of tuples t for which a predicate is true, written as {t | P(t)}.'),
    ('Domain relational calculus', 'Describes the result by listing the domains of its attributes with conditions on them.'),
    ('Expressiveness and safety', 'Both calculi are equivalent in power to relational algebra; safe expressions avoid infinite results.')]),
  ('Overview of Commercial RDBMSs', 'Commercial systems such as Oracle, SQL Server, MySQL, PostgreSQL and DB2 implement SQL with vendor extensions.',
   [('Features to compare', 'Storage limits, concurrency control, recovery, partitioning, security, replication and cost.'),
    ('Oracle and SQL Server', 'Enterprise systems with PL/SQL and T-SQL procedural extensions and rich administration tools.'),
    ('MySQL and PostgreSQL', 'Widely used open source systems, one favoured for web applications and the other for standards compliance.')]),
  ('Database Design and Functional Dependencies', 'Good relational design starts from dependencies among attributes that reveal redundancy and update anomalies.',
   [('Informal design guidelines', 'Keep semantics clear, reduce redundancy and avoid NULL heavy relations.'),
    ('Functional dependency', 'X determines Y means any two tuples agreeing on X must also agree on Y, written X -> Y.'),
    ('Partial and transitive dependency', 'A partial dependency uses only part of a composite key; a transitive dependency reaches a non-key attribute through another non-key attribute.'),
    ('Armstrong axioms', 'Reflexivity, augmentation and transitivity generate all dependencies, with union, decomposition and pseudotransitivity as derived rules.'),
    ('Closure and candidate key computation', 'The closure of an attribute set gives everything it determines, and a minimal attribute set whose closure is the whole relation is a candidate key.'),
    ('Canonical cover', 'A minimal equivalent set of functional dependencies with no redundant dependencies or attributes.'),
    ('Decomposition and its properties', 'Splitting a relation into smaller relations, checked for lossless join and dependency preservation.')]),
  ('Normal Forms', 'Normalisation removes redundancy and anomalies by checking a relation against progressively stricter normal forms.',
   [('Why normalisation is needed', 'Unnormalised relations suffer update, insertion and deletion anomalies along with wasted space.'),
    ('1NF (First Normal Form)', 'All attributes hold atomic single values - no multivalued attributes or repeating groups.'),
    ('2NF (Second Normal Form)', 'In 1NF and no non-prime attribute is partially dependent on part of a candidate key.'),
    ('3NF (Third Normal Form)', 'In 2NF and no non-prime attribute is transitively dependent on a candidate key.'),
    ('BCNF (Boyce Codd Normal Form)', 'For every non trivial dependency X -> Y, X must be a super key - stricter than 3NF.'),
    ('4NF (Fourth Normal Form)', 'In BCNF and free of multivalued dependencies, which occur when independent multivalued facts are stored together.'),
    ('5NF (Fifth Normal Form)', 'Also called project join normal form, where a relation cannot be decomposed any further without loss.'),
    ('Denormalisation', 'Deliberately relaxing normal forms to reduce joins and improve read performance in reporting systems.')]),
  ('Query Processing and Cost Estimation', 'Query processing turns an SQL statement into an executable plan whose cost is estimated to pick the cheapest strategy.',
   [('Parsing, validation and translation', 'The query is checked for syntax and semantics and converted into a relational algebra expression.'),
    ('Optimisation and plan generation', 'Equivalent expressions and access paths are compared to choose an efficient execution plan.'),
    ('Algorithms for executing query operations', 'Full table scan or index scan for selection, nested loop, sort merge and hash join for joins, external sorting for large data.'),
    ('Cost estimation', 'Estimates block transfers and disk seeks using statistics such as number of tuples, block factor and selectivity.'),
    ('Heuristic optimisation rules', 'Push selections down, then projections, and perform the most restrictive operations first.')])
 ]),
 ('III', 'Transaction Processing, Concurrency and Recovery', [
  ('Transaction Processing and Properties', 'A transaction is a logical unit of work that must either complete fully or leave the database unchanged.',
   [('Transaction operations', 'read_item, write_item, commit and rollback are the basic operations of a transaction.'),
    ('ACID properties', 'Atomicity, consistency, isolation and durability describe the guarantees a DBMS must provide.'),
    ('Transaction states', 'Active, partially committed, committed, failed and aborted states trace the life of a transaction.'),
    ('Desirable additional properties', 'Fine granularity of data items and protection from crashes and concurrent interference.')]),
  ('Serializability', 'A schedule is serializable when its effect equals that of some serial order of the same transactions.',
   [('Schedules and their types', 'Serial schedules run transactions one after another; non-serial schedules interleave them.'),
    ('Conflict serializability', 'Two different transactions accessing the same item with at least one write conflict; the precedence graph must be acyclic.'),
    ('View serializability', 'A weaker condition requiring the same reads-from relations and the same final writes.'),
    ('Recoverable and cascade-less schedules', 'A schedule is recoverable if a transaction commits only after all transactions it read from have committed; cascading rollback is avoided by strict schedules.')]),
  ('Transaction Support in SQL', 'SQL supports explicit transaction control with COMMIT, ROLLBACK and SAVEPOINT statements and isolation levels.',
   [('COMMIT and ROLLBACK', 'COMMIT makes changes permanent while ROLLBACK undoes changes of the current transaction.'),
    ('SAVEPOINT and partial rollback', 'Marks an intermediate point to which the transaction can roll back without losing earlier work.'),
    ('Isolation levels', 'READ UNCOMMITTED, READ COMMITTED, REPEATABLE READ and SERIALIZABLE trade correctness against concurrency.'),
    ('Concurrency problems controlled by levels', 'Dirty read, non repeatable read and phantom read.')]),
  ('Locking Techniques', 'Locking prevents conflicting accesses by making a transaction acquire a lock before reading or writing an item.',
   [('Shared and exclusive locks', 'A shared lock allows reading by many transactions while an exclusive lock allows one writer and blocks everyone else.'),
    ('Binary locking versus shared exclusive locking', 'Binary locks are locked or unlocked; shared exclusive locks distinguish readers from writers.'),
    ('Two phase locking (2PL)', 'A growing phase acquires locks and a shrinking phase releases them, which guarantees conflict serializability.'),
    ('Strict and rigorous 2PL', 'Strict 2PL holds exclusive locks until commit, and rigorous 2PL holds all locks until commit, both easing recovery.'),
    ('Deadlock and starvation', 'Deadlock is a circular wait for locks and starvation is a transaction repeatedly losing the competition; both must be handled.'),
    ('Lock conversion', 'Upgrading a shared lock to exclusive or downgrading it the other way, which must respect the two phases.')]),
  ('Timestamp Ordering and Validation Techniques', 'Timestamp ordering orders transactions by their start time, and validation methods check for conflicts only at commit time.',
   [('Timestamp ordering protocol', 'Each item keeps the read and write timestamps of the last transaction that accessed it, and conflicting older operations are rejected and restarted.'),
    ('Thomas write rule', 'Ignores an obsolete write that a later transaction has already overwritten.'),
    ('Optimistic (validation based) concurrency control', 'Transactions run freely and are validated in three phases: read, validation and write.'),
    ('Comparison with locking', 'Timestamp and validation methods avoid deadlock because they never make a transaction wait for a lock.')]),
  ('Granularity of Data Items', 'Granularity refers to the size of the unit locked, from a single field up to the whole database.',
   [('Trade-off of granularity', 'Small items allow more concurrency but more lock overhead, while large items do the opposite.'),
    ('Multiple granularity locking', 'Locks are taken at several levels of the hierarchy with intention locks.'),
    ('Intention shared and intention exclusive locks', 'IS and IX locks on ancestors signal that a descendant will be locked in shared or exclusive mode.'),
    ('Compatibility of intention locks', 'The compatibility matrix decides which combinations may be granted at the same time.')]),
  ('Recovery Concepts', 'Recovery restores the database to a consistent state after a failure and ensures committed work is not lost.',
   [('Types of failure', 'Transaction failure, system crash, media failure and natural disasters need different recovery responses.'),
    ('Storage structure and stable storage', 'Volatile memory, non volatile disk and stable storage mirrored across sites define what survives a crash.'),
    ('Log based recovery', 'A log records before images, after images and transaction events; deferred and immediate update policies use it differently.'),
    ('Checkpoints', 'Periodically flush the log and buffers so that recovery need not scan the whole log.'),
    ('Shadow paging', 'Maintains a current and a shadow page table, switching atomically on commit, which avoids a log but fragments storage.'),
    ('ARIES recovery algorithm', 'Uses write ahead logging, repeating history and fuzzy checkpoints in analysis, redo and undo passes.')]),
  ('Database Security Issues', 'Database security protects data from unauthorised access, disclosure and modification.',
   [('Access control and authorisation', 'Discretionary and mandatory access control models grant privileges to users and roles.'),
    ('Views and query modification', 'Restricting a user to a view exposes only the rows and columns they may see.'),
    ('Encryption and auditing', 'Data is encrypted in storage or transit, and audit trails record who did what.'),
    ('Statistical database security', 'Statistical queries must not allow inference of individual values; techniques include query restriction, perturbation and auditing.')])
 ]),
 ('IV', 'Files, Hashing and Indexing', [
  ('File Organisation and Operations', 'A file is stored as records in blocks on disk, and its organisation decides how efficiently records are found and updated.',
   [('File operations', 'Insertion, deletion, modification and retrieval of records identified by a search key.'),
    ('Heap file organisation', 'Records are placed wherever space is free, which makes insertion fast but search slow.'),
    ('Sequential file organisation', 'Records are kept in order of a search key, so search and ordered retrieval are fast while insertion needs reorganisation.'),
    ('Hashing and indexed organisation', 'A hash function or index computes the location directly, trading space and maintenance for speed.'),
    ('Blocking factor and record layout', 'Fixed or variable length records are packed into blocks, and the blocking factor is the records per block.')]),
  ('Hashing Techniques', 'Hashing applies a function to the search key to compute the bucket where the record is stored.',
   [('Static hashing', 'A fixed number of buckets is chosen in advance; the file grows slowly and long overflow chains appear.'),
    ('Collision and overflow handling', 'Open addressing, chaining within a bucket and multiple hashing resolve records that map to a full bucket.'),
    ('Dynamic and extendible hashing', 'The number of buckets grows and shrinks with the data by splitting buckets and using a directory of pointer bits.'),
    ('Comparison of hashing with indexing', 'Hashing is excellent for equality searches but useless for range queries, where indexes are preferred.')]),
  ('Indexing and Types of Indexes', 'An index is an auxiliary file of key and pointer pairs that speeds up retrieval from the main file.',
   [('Primary index', 'Built on the ordered key field of a sequentially ordered file, with one entry per block.'),
    ('Clustering index', 'Defined on an ordered non key field, so several records can share the same index value.'),
    ('Secondary index', 'Built on a non ordered field, giving one entry per distinct value with pointers to blocks.'),
    ('Dense and sparse indexes', 'A dense index has an entry for every search key value while a sparse index has entries for some values only.'),
    ('Single level and multilevel indexes', 'When the index itself becomes large it is indexed again, forming a multilevel structure like an ISAM tree.'),
    ('Indexes on multiple keys', 'Composite indexes order by the concatenation of keys, and grid or partitioned hashing handles multiattribute equality queries.')]),
  ('B Tree and B+ Tree', 'B trees and B+ trees are balanced multilevel search structures designed for disk storage with a high branching factor.',
   [('B tree properties', 'All leaves are at the same level, nodes hold between a minimum and maximum number of keys, and a node with k keys has k + 1 children.'),
    ('B+ tree properties', 'Internal nodes hold only keys and pointers while all data pointers live in a linked list of leaves.'),
    ('Insertion in a B+ tree', 'Insert into the correct leaf and split it when full, pushing the middle key into the parent and possibly splitting upwards to the root.'),
    ('Deletion in a B+ tree', 'Remove the entry, redistribute keys with a sibling or merge nodes when a node falls below the minimum occupancy.'),
    ('B tree versus B+ tree', 'B trees store data pointers in internal nodes and B+ trees do not, so B+ trees have higher fan-out and faster range scans.'),
    ('Why B+ trees dominate databases', 'A high fan-out keeps the tree shallow, so a record is found in three or four disk accesses even for millions of records.')])
 ]),
 ('V', 'Special Purpose Databases', [
  ('Object Oriented Database Management Systems', 'An OODBMS stores objects with their methods and supports the object oriented features of programming languages directly.',
   [('Need for OODBMS', 'Applications with complex data such as CAD, multimedia and GIS suffer from the impedance mismatch between objects and tables.'),
    ('Features', 'Object identity, encapsulation, inheritance, polymorphism and persistence are supported natively.'),
    ('Object oriented data model', 'Objects have identity and state, classes define types, and relationships are captured through references and collections.'),
    ('Object oriented languages and persistence', 'Languages such as C++ and Java are extended with a persistent object store, or pure OO languages such as Smalltalk are used.'),
    ('Advantages and disadvantages', 'Excellent for complex data and navigational access, but weak for ad hoc queries and lacking a common standard.')]),
  ('Object Relational Databases', 'An object relational DBMS extends the relational model with objects, inheritance, complex types and methods.',
   [('Object relational features', 'User defined types, collections such as arrays and nested tables, references and object identifiers.'),
    ('Bridging objects and tables', 'Object relational mapping persists programming objects as rows and columns.'),
    ('Comparison of the three approaches', 'RDBMS flatten complex data, OODBMS lose SQL simplicity and ORDBMS keep both, which is why commercial systems follow this route.')]),
  ('XML and Semi-structured Data', 'XML is a text based, self describing format for exchanging hierarchical data between systems.',
   [('Structure of XML', 'A prolog, nested elements with tags, attributes, entities and text content form a well formed document.'),
    ('DTD and XML Schema', 'Define the allowed elements, attributes and structure, so documents can be validated.'),
    ('Parsing and querying XML', 'DOM and SAX parsers read documents and XPath, XQuery and XSLT select and transform the data.'),
    ('Storing XML in a database', 'Documents may be stored as CLOB values, shredded into tables or kept in native XML columns.')]),
  ('Temporal Databases', 'Temporal databases record time so that past, present and future states of the data can be queried.',
   [('Valid time and transaction time', 'Valid time is when a fact is true in the real world; transaction time is when it was stored in the database.'),
    ('Bitemporal databases', 'Track both kinds of time, allowing corrections and audit of what the system believed at any moment.'),
    ('Temporal operators', 'Queries use operators such as overlaps, contains, precedes and during on time intervals.'),
    ('Applications', 'Banking audit trails, medical records, insurance history and employee service records.')]),
  ('Mobile Databases', 'A mobile database runs on portable devices and synchronises with a central database over wireless links.',
   [('Challenges', 'Frequent disconnection, limited bandwidth, low battery and small memory change the design assumptions.'),
    ('Data synchronisation and replication', 'Changes made offline are reconciled later, which can raise conflicts that need resolution rules.'),
    ('Mobile transactions', 'Long lived, location dependent transactions require relaxed ACID properties in some systems.')]),
  ('Spatial Databases', 'Spatial databases store geometric objects such as points, lines and polygons and answer location based queries.',
   [('Spatial data types and queries', 'Point, line and region types support queries like "find all hospitals within 5 km".'),
    ('Spatial indexing', 'R trees, quad trees and grid files organise two dimensional data for fast region queries.'),
    ('Applications', 'Geographic information systems, maps, navigation, urban planning and location based services.')]),
  ('Case Study: Designing and Managing a Project Database', 'A case study ties the whole module together by taking one application from requirements to a working, normalised database.',
   [('Requirement analysis', 'Identify entities, attributes, relationships, constraints and reports the users need.'),
    ('Conceptual and logical design', 'Draw the ER diagram, map it to relations, choose keys and normalise up to 3NF or BCNF.'),
    ('Physical design and implementation', 'Choose file organisation, indexes, constraints, views, triggers and the required privileges.'),
    ('Maintenance and tuning', 'Monitor performance, rebuild indexes, back up regularly and handle schema evolution.')])
 ])
])
